// skid_buffer_tb: self-checking testbench for skid_buffer.
// Two lanes (WIDTH 8 and WIDTH 1) share the stimulus; each checks its DUT
// against a two-entry queue model on every clock edge.

module skid_buffer_tb_lane #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    input  wire             m_ready,
    input  wire [7:0]       src_data,
    output wire             s_ready,
    output wire             m_valid,
    output wire [WIDTH-1:0] m_data
);
    wire [WIDTH-1:0] s_data = src_data[WIDTH-1:0];

    skid_buffer #(.WIDTH(WIDTH)) dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready),
        .s_data  (s_data),
        .m_valid (m_valid),
        .m_ready (m_ready),
        .m_data  (m_data)
    );

    integer passed  = 0;
    integer failed  = 0;
    integer n_in    = 0;
    integer n_out   = 0;
    integer n_full  = 0;
    integer n_stall = 0;
    integer count   = 0;
    reg             known        = 1'b0;
    reg             hold_pending = 1'b0;
    reg [WIDTH-1:0] hold_data    = {WIDTH{1'b0}};
    reg [WIDTH-1:0] q0           = {WIDTH{1'b0}};
    reg [WIDTH-1:0] q1           = {WIDTH{1'b0}};
    reg             push         = 1'b0;
    reg             pop          = 1'b0;

    task chk(input cond, input [8*64-1:0] msg);
    begin
        if (cond) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("lane WIDTH=%0d t=%0t: %0s", WIDTH, $time, msg);
        end
    end
    endtask

    always @(posedge clk) begin
        // Outputs sampled here are the values before this edge.
        if (known) begin
            chk(m_valid === (count > 0), "m_valid does not match beats held");
            chk(s_ready === (count < 2), "s_ready does not match beats held");
            if (count > 0)
                chk(m_data === q0, "m_data is not the oldest beat held");
            if (hold_pending)
                chk((m_valid === 1'b1) && (m_data === hold_data),
                    "stalled beat did not hold");
            if (count == 2)
                n_full = n_full + 1;
        end
        hold_pending = known && rst_n && (m_valid === 1'b1) && (m_ready === 1'b0);
        hold_data    = m_data;
        if (hold_pending)
            n_stall = n_stall + 1;

        if (!rst_n) begin
            count        = 0;
            known        = 1'b1;
            hold_pending = 1'b0;
        end else if (known) begin
            push = s_valid && (count < 2);
            pop  = m_ready && (count > 0);
            if (pop) begin
                n_out = n_out + 1;
                q0    = q1;
                count = count - 1;
            end
            if (push) begin
                if (count == 0)
                    q0 = s_data;
                else
                    q1 = s_data;
                count = count + 1;
                n_in  = n_in + 1;
            end
        end
    end
endmodule

module skid_buffer_tb;
    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] src_data;
    reg  [7:0] seq;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    integer passed;
    integer failed;
    integer i;
    integer base8;
    integer base1;
    integer obase8;
    integer obase1;
    reg [31:0] r;
    reg        sv_r;
    reg        mr_r;
    reg [8*64-1:0] nonce;

    skid_buffer_tb_lane #(.WIDTH(8)) lane8 (
        .clk(clk), .rst_n(rst_n), .s_valid(s_valid), .m_ready(m_ready),
        .src_data(src_data), .s_ready(s_ready8), .m_valid(m_valid8),
        .m_data(m_data8)
    );

    skid_buffer_tb_lane #(.WIDTH(1)) lane1 (
        .clk(clk), .rst_n(rst_n), .s_valid(s_valid), .m_ready(m_ready),
        .src_data(src_data), .s_ready(s_ready1), .m_valid(m_valid1),
        .m_data(m_data1)
    );

    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    task chk(input cond, input [8*64-1:0] msg);
    begin
        if (cond) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("tb t=%0t: %0s", $time, msg);
        end
    end
    endtask

    // One clock cycle. Called just after a falling edge: apply the inputs,
    // flip them briefly to show that no output follows them within the
    // cycle, restore them, then take the rising edge.
    task step(input sv, input mr, input [7:0] d);
        reg       r8;
        reg       r1;
        reg       v8;
        reg       v1;
        reg [7:0] md8;
        reg       md1;
    begin
        s_valid  = sv;
        m_ready  = mr;
        src_data = d;
        #2;
        r8  = s_ready8;
        r1  = s_ready1;
        v8  = m_valid8;
        v1  = m_valid1;
        md8 = m_data8;
        md1 = m_data1[0];
        s_valid  = ~sv;
        m_ready  = ~mr;
        src_data = ~d;
        #1;
        chk((s_ready8 === r8) && (s_ready1 === r1),
            "s_ready moved with m_ready or s_valid inside a cycle");
        chk((m_valid8 === v8) && (m_valid1 === v1) &&
            (m_data8 === md8) && (m_data1[0] === md1),
            "m_valid or m_data moved with an input inside a cycle");
        s_valid  = sv;
        m_ready  = mr;
        src_data = d;
        @(posedge clk);
        @(negedge clk);
    end
    endtask

    initial begin
        passed   = 0;
        failed   = 0;
        seq      = 8'h00;
        nonce    = {64{8'h00}};
        rst_n    = 1'b0;
        s_valid  = 1'b0;
        m_ready  = 1'b0;
        src_data = 8'h00;

        @(negedge clk);

        // 1. Reset values.
        step(1'b0, 1'b0, 8'h00);
        step(1'b1, 1'b1, 8'h00);
        rst_n = 1'b1;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "m_valid not low after reset");
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "s_ready not high after reset");

        // 2. One-cycle latency.
        step(1'b1, 1'b1, 8'hA5);
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hA5) &&
            (m_valid1 === 1'b1) && (m_data1 === 1'b1),
            "beat not offered on the cycle after acceptance");
        step(1'b0, 1'b1, 8'h00);
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "m_valid not low after beat left");

        // 3. Long stream at full throughput.
        base8  = lane8.n_in;
        base1  = lane1.n_in;
        obase8 = lane8.n_out;
        obase1 = lane1.n_out;
        for (i = 0; i < 64; i = i + 1) begin
            step(1'b1, 1'b1, seq);
            seq = seq + 8'd1;
            chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "s_ready dropped at full throughput");
            chk((m_valid8 === 1'b1) && (m_valid1 === 1'b1), "bubble at full throughput");
        end
        chk((lane8.n_in - base8 == 64) && (lane1.n_in - base1 == 64),
            "not one beat accepted per edge at full throughput");
        chk((lane8.n_out - obase8 == 63) && (lane1.n_out - obase1 == 63),
            "not one beat delivered per edge at full throughput");
        step(1'b0, 1'b1, 8'h00);
        chk((m_valid8 === 1'b0) && (lane8.count == 0) && (lane1.count == 0),
            "slice not empty after full-throughput stream");

        // 4. Stall with one beat held, then with two.
        step(1'b1, 1'b0, 8'h11);
        chk((m_valid8 === 1'b1) && (m_data8 === 8'h11), "first stalled beat not offered");
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "s_ready low with one beat held");
        base8 = lane8.n_in;
        base1 = lane1.n_in;
        step(1'b1, 1'b0, 8'h22);
        chk((lane8.n_in == base8 + 1) && (lane1.n_in == base1 + 1),
            "second beat not accepted during stall");
        chk((s_ready8 === 1'b0) && (s_ready1 === 1'b0), "s_ready high with two beats held");
        chk((m_valid8 === 1'b1) && (m_data8 === 8'h11), "offered beat changed during stall");
        for (i = 0; i < 5; i = i + 1) begin
            step(1'b1, 1'b0, 8'h33 + i[7:0]);
            chk((lane8.n_in == base8 + 1) && (lane1.n_in == base1 + 1),
                "third beat accepted with two held");
            chk((s_ready8 === 1'b0) && (s_ready1 === 1'b0), "s_ready rose during long stall");
            chk((m_valid8 === 1'b1) && (m_data8 === 8'h11), "offered beat changed in long stall");
        end

        // 5. Ready rises after the stall: every beat out, in order, once.
        step(1'b0, 1'b1, 8'h00);
        chk((m_valid8 === 1'b1) && (m_data8 === 8'h22), "skid beat not next after stall");
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "s_ready did not rise after a beat left");
        step(1'b1, 1'b1, 8'h55);
        chk((m_valid8 === 1'b1) && (m_data8 === 8'h55), "beat after stall not offered");
        step(1'b0, 1'b1, 8'h00);
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "slice not empty after stall drain");
        chk((lane8.n_in == lane8.n_out) && (lane1.n_in == lane1.n_out),
            "beats in and out differ after stall drain");

        // 6. Random traffic against the model, then a drain.
        for (i = 0; i < 3000; i = i + 1) begin
            r = $random;
            if (i < 1000) begin
                sv_r = r[0];
                mr_r = r[1];
            end else if (i < 2000) begin
                sv_r = |r[3:2];
                mr_r = &r[5:4];
            end else begin
                sv_r = &r[7:6];
                mr_r = |r[9:8];
            end
            step(sv_r, mr_r, r[23:16]);
        end
        for (i = 0; i < 4; i = i + 1)
            step(1'b0, 1'b1, 8'h00);
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "m_valid high after random drain");
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "s_ready low after random drain");
        chk((lane8.n_in == lane8.n_out) && (lane1.n_in == lane1.n_out),
            "beats in and out differ after random drain");
        chk((lane8.n_full > 0) && (lane1.n_full > 0), "random traffic never filled the slice");
        chk((lane8.n_stall > 0) && (lane1.n_stall > 0), "random traffic never stalled");

        // 7. Reset with two beats held.
        step(1'b1, 1'b0, 8'h66);
        step(1'b1, 1'b0, 8'h77);
        chk((s_ready8 === 1'b0) && (s_ready1 === 1'b0) && (m_valid8 === 1'b1),
            "slice did not fill before reset");
        rst_n = 1'b0;
        step(1'b1, 1'b0, 8'h88);
        rst_n = 1'b1;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "reset did not drop held beats");
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "s_ready not high after reset with beats");
        step(1'b1, 1'b1, 8'h99);
        chk((m_valid8 === 1'b1) && (m_data8 === 8'h99), "beat after reset not offered");
        step(1'b0, 1'b1, 8'h00);
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "slice not empty at end");

        passed = passed + lane8.passed + lane1.passed;
        failed = failed + lane8.failed + lane1.failed;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = {64{8'h00}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
